//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::sint::int8_to_float32`; the
//! native twin is `benches/native/Bench/Int8ToFloat32.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::{float32, sint};
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0.0f32);
    for _ in 0..n {
        x = step(x);
        acc += sint::int8_to_float32((x >> 56) as u8);
    }
    float32::to_bits(acc) as u64
}

fn main() {
    run(|| (), kernel)
}
